// Create an allocator for extranonces of `total_extranonce_len` bytes
// (at most 32) that start with the `local_prefix_len` bytes at
// `local_prefix` and have room for `max_channels` channels at once.
// Returns NULL when the prefix and the index do not fit, or
// `max_channels` is 0.  Free with `sv2_sri_extranonce_allocator_free()`
// after every channel opened through it.
//
// # Safety
// `local_prefix` must point at `local_prefix_len` readable bytes, or be
// NULL when that is 0.
struct Sv2SriExtranonceAllocator *sv2_sri_extranonce_allocator_new(const uint8_t *local_prefix,
                                                                   uint32_t local_prefix_len,
                                                                   uint8_t total_extranonce_len,
                                                                   uint32_t max_channels);

// # Safety
// `a` must be NULL or a pointer from `sv2_sri_extranonce_allocator_new()`,
// not freed before, with no channel opened through it still alive.
void sv2_sri_extranonce_allocator_free(struct Sv2SriExtranonceAllocator *a);

// The rollable bytes an extended channel of this allocator gets, or
// `SV2_SRI_ERR_INVALID`.
//
// # Safety
// `a` must be a live allocator.
int32_t sv2_sri_extranonce_allocator_rollable_size(const struct Sv2SriExtranonceAllocator *a);

// Open an extended channel with a prefix from `allocator`; the miner rolls
// the allocator's rollable bytes (`sv2_sri_extranonce_allocator_rollable_size()`).
// Version rolling is allowed unless `no_version_rolling` is set.  Returns
// NULL with `*status` set when the request is refused.  Free with
// `sv2_sri_extended_channel_free()`.
//
// # Safety
// `allocator` must be a live allocator, `o` must point at a record whose
// byte fields describe readable memory and whose `max_target` points at 32
// bytes, and `status` must be NULL or writable.
struct Sv2SriExtendedChannel *sv2_sri_extended_channel_new(struct Sv2SriExtranonceAllocator *allocator,
                                                           const struct Sv2SriChannelOpen *o,
                                                           int32_t *status);

// # Safety
// `ch` must be NULL or a pointer from `sv2_sri_extended_channel_new()`,
// not freed before.
void sv2_sri_extended_channel_free(struct Sv2SriExtendedChannel *ch);

// The channel's extranonce prefix, written to `out` (capacity `cap`).
// Returns its length, or `SV2_SRI_ERR_OVERFLOW`.
//
// # Safety
// `ch` must be a live channel and `out` must point at `cap` writable bytes.
